      finished: { kilnOutput: sum(finishedRows, 'kilnOutput'), finished: sum(finishedRows, 'finished'),
        tagged: sum(finishedRows, 'tagged'), tested: sum(finishedRows, 'tested'), untagged: sum(finishedRows, 'untagged') },
      linearFt: { input: rawFt('input'), completed: rawFt('completed'), unplanned: rawFt('unplanned'),
        finished: finishedFt('finished'), untagged: finishedFt('untagged'), removed: removedFt },
