  const row = (lengthFt, material) => {
    const key = tagPlanningKey(lengthFt, material || species);
    if (!rows.has(key)) rows.set(key, { key, lengthFt:num(lengthFt), material:material || species,
      kilnOutput:0, recoveryIn:0, recoveryOut:0, tagged:0, tested:0, reservedReady:0, expected:0, reservedExpected:0, forecast:0 });
    return rows.get(key);
  };

  (input.kilnOutput || []).forEach(cycle => positive(cycle.lots).forEach(lot => { row(lot.lengthFt, lot.material).kilnOutput += num(lot.quantity); }));

  // A cut consumes a source length and adds shorter pieces of the same material.
  (input.recoveries || []).forEach(recovery => {
    const source = num(recovery.sourceLengthFt);
    const candidates = [...rows.values()].filter(item => item.lengthFt === source && item.kilnOutput + item.recoveryOut - item.recoveryIn > 0);
    const material = candidates.length === 1 ? candidates[0].material
      : (candidates.find(item => item.material === species) || candidates[0] || { material:species }).material;
    if (candidates.length > 1) issues.push({ level:'warning', code:'RECOVERY_MATERIAL_ASSUMED',
      message:`Recovery ${recovery.id}: ${source} ft exists in several materials; ${material} was used.` });
    row(source, material).recoveryIn += num(recovery.quantity);
    (recovery.piecesFt || []).forEach(piece => { row(piece, material).recoveryOut += num(recovery.quantity); });
  });

